def load_raw(path: str = DATA_PATH) -> pd.DataFrame:
    """读取原始客户账单数据。"""
    return pd.read_csv(path)

def score_to_rating(probability: float) -> str:
    """把违约概率映射为内部评级（历史规则）。"""
    if probability < 0.1:
        return "A"
    if probability < 0.3:
        return "B"
    if probability < 0.5:
        return "C"
    return "D"
